import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/structure/commands.md","filePath":"modules/structure/commands.md","lastUpdated":0}`),a={name:`modules/structure/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>主命令 <code>/emakistructure</code>, 别名 <code>/ems</code>, <code>/estruct</code>. 不带子命令执行时输出用法提示; 未知子命令提示使用 <code>/ems help</code></p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/ems help</code></td><td>无 (所有人)</td><td>输出命令帮助列表</td></tr><tr><td><code>/ems get &lt;模板&gt; [朝向]</code></td><td><code>emakistructure.use</code></td><td>在执行者面前 3 格处预览生成指定结构模板 (不写盘, 不进事务记录), 用于试放</td></tr><tr><td><code>/ems select pos1</code> / <code>pos2</code></td><td><code>emakistructure.edit</code></td><td>把执行者当前站位设为选区第一/第二角点. 两点须在同一世界, 跨世界设置会提示</td></tr><tr><td><code>/ems select adjust &lt;add|reduce&gt; &lt;front|back|left|right|up|down&gt; &lt;数值&gt;</code></td><td><code>emakistructure.edit</code></td><td>沿指定方向扩大或缩小选区; 收缩超过边界时报&quot;收缩过多&quot;</td></tr><tr><td><code>/ems select clear</code></td><td><code>emakistructure.edit</code></td><td>清除当前选区与高亮</td></tr><tr><td><code>/ems structure export &lt;名称&gt;</code></td><td><code>emakistructure.edit</code></td><td>把当前选区导出为结构模板 <code>structures/&lt;名称&gt;.nbt</code> (原版 <code>.nbt</code> 结构文件, 非多方块定义)</td></tr><tr><td><code>/ems structure place &lt;模板&gt; &lt;朝向&gt;</code></td><td><code>emakistructure.edit</code></td><td>在执行者当前位置放置结构模板; 朝向见下文. 多方块结构请用 <code>/ems multiblock place</code></td></tr><tr><td><code>/ems multiblock export &lt;id&gt; [force]</code></td><td><code>emakistructure.edit</code></td><td>按选区导出多方块布局为 <code>multiblocks/&lt;id&gt;.yml</code> (仅记录, 不放置). <code>id</code> 已存在时需 <code>force</code> 覆盖</td></tr><tr><td><code>/ems multiblock place &lt;id&gt; [朝向]</code></td><td><code>emakistructure.edit</code></td><td>在执行者当前位置放置多方块结构定义: 原版方块, 自定义方块与家具三类成员按朝向落位, 完成后自动进行形成检测</td></tr><tr><td><code>/ems multiblock list</code></td><td><code>emakistructure.admin</code></td><td>列出全部已加载多方块定义, 回显成员数, 旋转能力, 进行中实例与活动实例计数</td></tr><tr><td><code>/ems multiblock validate &lt;id&gt;</code></td><td><code>emakistructure.admin</code></td><td>手动校验该定义在现场的形状, 回显成员数, 无法解析的自定义方块, 缺失家具源与实例计数</td></tr><tr><td><code>/ems reload</code></td><td><code>emakistructure.reload</code></td><td>重载配置, 语言与模板缓存, 回显已加载模板数</td></tr><tr><td><code>/ems debug ...</code></td><td><code>emakistructure.admin</code></td><td>转发给 CoreLib 调试命令 (模块过滤为 <code>structure</code>), 管理 Debug 模式与诊断输出</td></tr></tbody></table><h2 id="朝向参数" tabindex="-1">朝向参数 <a class="header-anchor" href="#朝向参数" aria-label="Permalink to “朝向参数”">​</a></h2><p><code>get</code>, <code>structure place</code>, <code>multiblock place</code> 的 <code>[朝向]</code> 接受 8 个值:</p><table tabindex="0"><thead><tr><th>取值</th><th>含义</th></tr></thead><tbody><tr><td><code>north</code> / <code>east</code> / <code>south</code> / <code>west</code></td><td>仅旋转, 不镜像</td></tr><tr><td><code>north_mirror</code> / <code>east_mirror</code> / <code>south_mirror</code> / <code>west_mirror</code></td><td>旋转并左右镜像</td></tr></tbody></table><p>省略朝向时按执行者的朝向取最近的四分之一方向. 取值非法时提示可用值列表</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><p><code>paper-plugin.yml</code> 声明的权限及默认值:</p><table tabindex="0"><thead><tr><th>权限</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>emakistructure.use</code></td><td><code>true</code> (所有玩家)</td><td>预览生成 <code>get</code></td></tr><tr><td><code>emakistructure.edit</code></td><td><code>op</code></td><td>框选, 结构导出/放置, 多方块导出/放置</td></tr><tr><td><code>emakistructure.reload</code></td><td><code>op</code></td><td>重载配置</td></tr><tr><td><code>emakistructure.admin</code></td><td><code>op</code></td><td>管理与诊断: <code>multiblock list</code> / <code>validate</code>, <code>debug</code>; 含全部上述子权限</td></tr></tbody></table><p>Tab 补全按执行者权限过滤子命令, 并补全模板名, 多方块 id, 朝向值, <code>adjust</code> 的操作/方向与 <code>select</code> 的操作名</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to “使用示例”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 框选一个 12×8×12 的区域</span></span>
<span class="line"><span>/ems select pos1</span></span>
<span class="line"><span>/ems select pos2</span></span>
<span class="line"><span>/ems select adjust add up 3</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 导出为结构模板并就地预览</span></span>
<span class="line"><span>/ems structure export village_hub_a</span></span>
<span class="line"><span>/ems get village_hub_a north</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 朝南放置</span></span>
<span class="line"><span>/ems structure place village_hub_a south</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 记录一个多方块结构 (按选区)</span></span>
<span class="line"><span>/ems multiblock export teleporter</span></span>
<span class="line"><span>/ems multiblock place teleporter east</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看已加载的多方块定义与状态</span></span>
<span class="line"><span>/ems multiblock list</span></span>
<span class="line"><span>/ems multiblock validate teleporter</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 重载</span></span>
<span class="line"><span>/ems reload</span></span></code></pre></div><div class="caution custom-block"><p class="custom-block-title custom-block-title-default">CAUTION</p><p><code>structure export</code> 导出的是<strong>原版 <code>.nbt</code> 结构文件</strong> (<code>structures/</code> 目录), <code>multiblock export</code> 导出的是<strong>多方块布局定义</strong> (<code>multiblocks/</code> 目录). 两者互不通用, 放置时也不可互换</p></div>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};